        {
          "type": "object",
          "required": ["path"],
          "properties": {
            "path": {
              "type": "string"
            },
            "selectors": {
              "type": "array",
              "items": {
                "anyOf": [
                  {
                    "type": "string"
                  }
                ]
              }
            },
            "values": {
              "type": "array",
              "items": {
                "anyOf": [
                  {
                    "type": "string"
                  },
                  {
                    "type": "object",
                    "properties": {
                      "key1": {
                        "type": "string"
                      }
                    }
                  }
                ]
              }
            }
          }
        }
      ]
    },
    "missingFileHandler": {
      "type": "string",
      "enum": ["Error", "Warn", "Info", "Debug"]
    },
    "environment": {
      "type": "object",
      "properties": {
        "values": {
          "type": "array",
          "items": {
            "anyOf": [
              {
                "type": "string"
              },
              {
                "$ref": "#/definitions/map"
              }
            ]
          }
        },
        "secrets": {
          "type": "array",
          "items": {
            "type": "string"
          }
