          "type": "boolean"
        },
        "command": {
          "type": "string"
        },
        "args": {
          "type": "array",
          "items": {
            "anyOf": [
              {
                "type": "string"
              },
              {
                "type": "string"
              }
            ]
          }
        }
      }
    },
    "map": {
      "type": "object",
      "patternProperties": {
        "[a-zA-Z\\d_-]+": {
          "anyOf": [
            {
              "type": "object"
