      "allOf": [
        {
          "$ref": "#/definitions/base"
        }
      ]
    },
    "transform_messes_up_line_numbers": {
      "description": "This rule detects when changes are made by transform function, and warns that line numbers are probably incorrect. [default level: warn]",
      "allOf": [
        {
          "$ref": "#/definitions/base"
        }
      ]
    }
  },
