            },
            {
              "type": "boolean"
            },
            {
              "type": "object",
              "$ref": "#/definitions/allRules",
              "properties": {
                "forbid-in-block-mappings": {
                  "title": "Forbid in Block Mappings",
                  "description": "Prevent empty values in block mappings.",
                  "type": "boolean",
                  "default": true
                },
                "forbid-in-flow-mappings": {
                  "title": "Forbid in Flow Mappings",
