          "body": {}
        },
        "ignoreTestFiles": {
          "type": [
            "string",
            "array"
          ],
          "items": {
            "type": "string"
          },
          "description": "A String or Array of glob patterns used to ignore test files that would otherwise be shown in your list of tests. Cypress uses minimatch with the options: {dot: true, matchBase: true}. We suggest using http://globtester.com to test what files would match."
        },
        "numTestsKeptInMemory": {
          "type": "number",
          "default": 50,
          "description": "The number of tests for which snapshots and command data are kept in memory. Reduce this number if you are experiencing high memory consumption in your browser during a test run."
        },
        "port": {
          "type": "number",
          "default": null,
          "description": "Port used to host Cypress. Normally this is a randomly generated port"
        },
        "reporter": {
          "type": "string",
          "default": "spec",
          "description": "The reporter used when running headlessly or in CI. See https://on.cypress.io/reporters"
        },
        "reporterOptions": {
          "type": "object",
          "default": null,
          "description": "The reporter options used. Supported options depend on the reporter. See https://on.cypress.io/reporters#Reporter-Options"
        },
        "slowTestThreshold": {
          "type": "number",
          "default": 10000,
          "description": "Slow test threshold in milliseconds. Only affects the visual output of some reporters. For example, the spec reporter will display the test time in yellow if over the threshold. See https://on.cypress.io/configuration#Timeouts"
        },
        "testFiles": {
          "type": [
            "string",
            "array"
          ],
          "default": "**/*.*",
          "description": "A String or Array of string glob patterns of the test files to load. See https://on.cypress.io/configuration#Global"
        },
        "watchForFileChanges": {
          "type": "boolean",
          "default": true,
          "description": "Whether Cypress will watch and restart tests on test file changes"
        },
        "defaultCommandTimeout": {
          "type": "number",
          "default": 4000,
          "description": "Time, in milliseconds, to wait until most DOM based commands are considered timed out"
        },
        "execTimeout": {
          "type": "number",
          "default": 60000,
          "description": "Time, in milliseconds, to wait for a system command to finish executing during a cy.exec() command"
        },
        "taskTimeout": {
          "type": "number",
          "default": 60000,
          "description": "Time, in milliseconds, to wait for a task to finish executing during a cy.task() command"
        },
        "pageLoadTimeout": {
          "type": "number",
          "default": 60000,
          "description": "Time, in milliseconds, to wait for page transition events or cy.visit(), cy.go(), cy.reload() commands to fire their page load events. Network requests are limited by the underlying operating system, and may still time out if this value is increased."
        },
        "requestTimeout": {
          "type": "number",
          "default": 5000,
          "description": "Time, in milliseconds, to wait for an XHR request to go out in a cy.wait() command"
        },
        "responseTimeout": {
          "type": "number",
          "default": 30000,
          "description": "Time, in milliseconds, to wait until a response in a cy.request(), cy.wait(), cy.fixture(), cy.getCookie(), cy.getCookies(), cy.setCookie(), cy.clearCookie(), cy.clearCookies(), and cy.screenshot() commands"
        },
        "fileServerFolder": {
          "type": "string",
          "default": "root project folder",
          "description": "Path to folder where application files will attempt to be served from"
        },
        "fixturesFolder": {
          "type": [
            "string",
            "boolean"
          ],
          "default": "cypress/fixtures",
          "description": "Path to folder containing fixture files (Pass false to disable)"
        },
        "integrationFolder": {
          "type": "string",
          "default": "cypress/integration",
          "description": "Path to folder containing integration test files"
        },
        "downloadsFolder": {
          "type": "string",
          "default": "cypress/downloads",
          "description": "Path to folder where files downloaded during a test are saved"
        },
        "componentFolder": {
          "type": [
            "string",
            "boolean"
          ],
          "default": false,
          "description": "Path to folder containing component test files (Pass false to disable)"
        },
        "pluginsFile": {
          "type": [
            "string",
            "boolean"
          ],
          "default": "cypress/plugins/index.js",
          "description": "Path to plugins file. (Pass false to disable)"
        },
        "screenshotOnRunFailure": {
          "type": "boolean",
          "default": true,
          "description": "Whether Cypress will take a screenshot when a test fails during cypress run"
        },
        "screenshotsFolder": {
          "type": "string",
          "default": "cypress/screenshots",
          "description": "Path to folder where screenshots will be saved from cy.screenshot() command or after a test fails during cypress run"
        },
        "supportFile": {
          "type": [
            "string",
            "boolean"
          ],
          "default": "cypress/support/index.js",
          "description": "Path to file to load before test files load. This file is compiled and bundled. (Pass false to disable)"
        },
        "videosFolder": {
          "type": "string",
          "default": "cypress/videos",
          "description": "Path to folder where videos will be saved during cypress run"
        },
        "trashAssetsBeforeRuns": {
          "type": "boolean",
          "default": true,
          "description": "Whether Cypress will trash assets within the screenshotsFolder and videosFolder before tests run with cypress run"
        },
        "videoCompression": {
          "type": [
            "number",
            "boolean"
          ],
          "default": 32,
          "description": "The quality setting for the video compression, in Constant Rate Factor (CRF). The value can be false to disable compression or a value between 0 and 51, where a lower value results in better quality (at the expense of a higher file size)."
        },
        "video": {
          "type": "boolean",
          "default": true,
          "description": "Whether Cypress will capture a video of the tests run with cypress run"
        },
        "videoUploadOnPasses": {
          "type": "boolean",
          "default": true,
          "description": "Whether Cypress will process, compress, and upload videos to the Dashboard even when all tests in a spec file are passing. This only applies when recording your runs to the Dashboard. Turn this off if you’d like to only upload the spec file’s video when there are failing tests."
        },
        "chromeWebSecurity": {
          "type": "boolean",
          "default": true,
          "description": "Whether Chrome Web Security for same-origin policy and insecure mixed content is enabled. Read more about this at https://on.cypress.io/web-security"
        },
        "userAgent": {
          "type": "string",
          "default": null,
          "description": "Enables you to override the default user agent the browser sends in all request headers. User agent values are typically used by servers to help identify the operating system, browser, and browser version. See User-Agent MDN Documentation for example user agent values here: https://developer.mozilla.org/en-US/docs/Web/HTTP/Headers/User-Agent"
        },
        "blockHosts": {
          "type": [
            "string",
            "array"
          ],
          "items": {
            "type": "string"
          },
          "default": null,
          "description": "A String or Array of hosts that you wish to block traffic for. Please read the notes for examples on using this https://on.cypress.io/configuration#blockHosts"
        },
        "modifyObstructiveCode": {
          "type": "boolean",
          "default": true,
          "description": "Whether Cypress will search for and replace obstructive JS code found in .js or .html files that prevent Cypress from working. Please read the notes for more information on this setting. https://on.cypress.io/configuration#modifyObstructiveCode"
        },
        "viewportHeight": {
          "type": "number",
          "default": 660,
          "description": "Default height in pixels for the application under tests’ viewport (Override with cy.viewport() command)"
        },
        "viewportWidth": {
          "type": "number",
          "default": 1000,
          "description": "Default width in pixels for the application under tests’ viewport. (Override with cy.viewport() command)"
        },
        "animationDistanceThreshold": {
          "type": "number",
          "default": 5,
          "description": "The distance in pixels an element must exceed over time to be considered animating"
        },
        "waitForAnimations": {
          "type": "boolean",
          "default": true,
          "description": "Whether to wait for elements to finish animating before executing commands"
        },
        "scrollBehavior": {
          "enum": [
            false,
            "center",
            "top",
            "bottom",
            "nearest"
          ],
          "default": "top",
          "description": "Viewport position to which an element should be scrolled prior to action commands. Setting `false` disables scrolling."
        },
        "projectId": {
          "type": "string",
          "default": null,
          "description": "A 6 character string use to identify this project in the Cypress Dashboard. See https://on.cypress.io/dashboard-service#Identification"
        },
        "nodeVersion": {
          "enum": [
            "system",
            "bundled"
          ],
          "default": "system",
          "description": "DEPRECATED: If set to 'bundled', Cypress will use the Node version bundled with Cypress. Otherwise, Cypress will use the Node version that was used to launch the Cypress. This Node version is used when executing your plugins file and building spec files."
        },
        "experimentalInteractiveRunEvents": {
          "type": "boolean",
          "default": false,
          "description": "Allows listening to the `before:run`, `after:run`, `before:spec`, and `after:spec` events in the plugins file during interactive mode."
        },
        "experimentalSourceRewriting": {
          "type": "boolean",
          "default": false,
          "description": "Enables AST-based JS/HTML rewriting. This may fix issues caused by the existing regex-based JS/HTML replacement algorithm."
        },
        "experimentalSessionSupport": {
          "type": "boolean",
          "default": false,
          "description": "Enable experimental session support. See https://on.cypress.io/session"
        },
        "experimentalFetchPolyfill": {
          "type": "boolean",
          "default": false,
          "description": "Polyfills `window.fetch` to enable Network spying and stubbing"
        },
        "experimentalStudio": {
          "type": "boolean",
          "default": false,
          "description": "Generate and save commands directly to your test suite by interacting with your app as an end user would."
        },
        "retries": {
          "type": [
            "object",
            "number",
            "null"
          ],
          "default": {
            "runMode": 0,
            "openMode": 0
          },
          "description": "The number of times to retry a failing. Can be configured to apply only in runMode or openMode"
        },
        "includeShadowDom": {
          "type": "boolean",
          "default": false,
          "description": "Enables including elements within the shadow DOM when using querying commands (e.g. cy.get(), cy.find()). Can be set globally in cypress.json, per-suite or per-test in the test configuration object, or programmatically with Cypress.config()"
        },
        "clientCertificates": {
          "description": "Defines client certificates to use when sending requests to the specified URLs",
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "url": {
                "description": "Requests for URLs matching this minimatch pattern will use the supplied client certificate",
                "type": "string"
              },
              "ca": {
                "description": "Path(s) to CA file(s) to validate certs against, relative to project root",
                "type": "array",
                "items": {
                  "type": "string"
                }
              },
              "certs": {
                "type": "array",
                "items": {
                  "anyOf": [
                    {
                      "description": "PEM file specific properties",
                      "type": "object",
                      "properties": {
                        "cert": {
                          "description": "Path to the certificate, relative to project root",
                          "type": "string"
                        },
                        "key": {
                          "description": "Path to the private key, relative to project root",
                          "type": "string"
                        },
                        "passphrase": {
                          "description": "(Optional) File path to a UTF-8 text file containing the passphrase for the key, relative to project root",
                          "type": "string"
                        }
                      },
                      "required": [
                        "cert",
                        "key"
                      ]
                    },
                    {
                      "description": "PFX file specific properties",
                      "type": "object",
                      "properties": {
                        "pfx": {
                          "description": "Path to the certificate container, relative to project root",
                          "type": "string"
                        },
                        "passphrase": {
                          "description": "(Optional) File path to a UTF-8 text file containing the passphrase for the container, relative to project root",
                          "type": "string"
                        }
                      },
                      "required": [
                        "pfx"
                      ]
                    }
                  ]
                }
              }
            },
            "required": [
              "url",
              "certs"
            ]
          }
        }
      }
    }
  },
  "allOf": [
    {
      "$ref": "#/definitions/cypressConfig"
    },
    {
      "properties": {
        "component": {
          "description": "Any component runner specific overrides",
          "$ref": "#/definitions/cypressConfig"
        },
        "e2e": {
          "description": "Any e2e runner specific overrides",
          "$ref": "#/definitions/cypressConfig"
        }
      }
    }
  ]
}

{
    "$schema": "https://json-schema.org/draft/2020-12/schema",
    "title": "shopware-cli",
    "$ref": "#/definitions/Config",
    "description": "shopware cli extension configuration definition file",
    "definitions": {
        "Config": {
            "type": "object",
            "title": ".shopware-extension.yml",
            "additionalProperties": false,
            "properties": {
                "build": {
                    "$ref": "#/definitions/Build"
                },
                "store": {
                    "$ref": "#/definitions/Store"
                },
                "changelog": {
                    "$ref": "#/definitions/Changelog"
                }
            }
        },
        "Changelog": {
            "type": "object",
            "title": "changelog",
            "additionalProperties": false,
            "properties": {
                "enabled": {
                    "type": "boolean",
                    "default": false,
                    "description": "Enables the changelog generation."
                },
                "ai_enabled": {
                    "type": "boolean",
                    "default": false,
                    "description": "Enables the changelog generation with OpenAI (Requires OPENAI_TOKEN environment variable)."
                },
                "pattern": {
                    "type": "string",
                    "default": "",
                    "description": "Limit with RegEx which commits should be considered for the changelog generation."
                },
                "template": {
                    "type": "string",
                    "default": "",
                    "description": "Allows to override the Go template which renders the Changelog."
                },
                "variables": {
                    "type": "object",
                    "description": "Allows to write RegEx groups into variables which can be used in the template."
                }
            }
        },
        "Build": {
            "type": "object",
            "title": "build",
            "additionalProperties": false,
            "properties": {
                "shopwareVersionConstraint": {
                    "type": "string",
                    "description": "Overrides the shopware version constraint in the composer.json/manifest.xml file."
                },
                "extraBundles": {
                    "type": "array",
                    "items": {
                        "type": "object",
                        "additionalProperties": false,
                        "required": ["path"],
                        "properties": {
                            "name": {
                                "type": "string"
                            },
                            "path": {
                                "type": "string"
                            }
                        }
                    }
                },
                "zip": {
                    "type": "object",
                    "additionalProperties": false,
                    "properties": {
                        "composer": {
                            "type": "object",
                            "additionalProperties": false,
                            "properties": {
                                "enabled": {
                                    "type": "boolean",
                                    "default": true
                                },
                                "before_hooks": {
                                    "type": "array",
                                    "items": {"type": "string"}
                                },
                                "after_hooks": {
                                    "type": "array",
                                    "items": {"type": "string"}
                                },
                                "excluded_packages": {
                                    "type": "array",
                                    "items": {"type": "string"}
                                }
                            }
                        },
                        "assets": {
                            "type": "object",
                            "additionalProperties": false,
                            "properties": {
                                "enabled": {
                                    "type": "boolean",
                                    "default": true
                                },
                                "before_hooks": {
                                    "type": "array",
                                    "items": {"type": "string"}
                                },
                                "after_hooks": {
                                    "type": "array",
                                    "items": {"type": "string"}
                                },
                                "enable_es_build_for_admin": {
                                    "type": "boolean",
                                    "default": false
                                },
                                "enable_es_build_for_storefront": {
                                    "type": "boolean",
                                    "default": false
                                }
                            }
                        },
                        "pack": {
                            "type": "object",
                            "additionalProperties": false,
                            "properties": {
                                "before_hooks": {
                                    "type": "array",
                                    "items": {"type": "string"}
                                },
                                "excludes": {
                                    "type": "object",
                                    "additionalProperties": false,
                                    "minProperties": 1,
                                    "properties": {
                                        "paths": {
                                            "type": "array",
                                            "items": {"type": "string"}
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        },
        "Store": {
            "type": "object",
            "title": "store",
            "additionalProperties": false,
            "properties": {
                "icon": {
                    "type": "string",
                    "description": "Specifies the Path to the icon (128x128 px) for store."
                },
                "availabilities": {
                    "type": "array",
                    "description": "Specifies the visibility in stores.",
                    "uniqueItems": true,
                    "items": {
                        "type": "string",
                        "enum": [
                            "German",
                            "International"
                        ]
                    }
                },
                "localizations": {
                    "type": "array",
                    "description": "Specifies the languages the extension is translated.",
                    "uniqueItems": true,
                    "items": {
                        "type": "string",
                        "enum": [
                            "de_DE",
                            "en_GB",
                            "es_ES",
                            "fi_FI",
                            "fr_FR",
                            "it_IT",
                            "nb_NO",
                            "nl_NL",
                            "pl_PL",
                            "sv_SE",
                            "bg_BG",
                            "cs_CZ",
                            "pt_PT",
                            "hy",
                            "de_CH",
                            "tr",
                            "da_DK",
                            "ru_RU"
                        ]
                    }
                },
                "categories": {
                    "type": "array",
                    "description": "Specifies the categories in which the extension can be found.",
                    "uniqueItems": true,
                    "maxItems": 1,
                    "items": {
                        "type": "string",
                        "enum": [
                            "Administration",
                            "SEOOptimierung",
                            "Bonitaetsprüfung",
                            "Rechtssicherheit",
                            "Auswertung",
                            "KommentarFeedback",
                            "Tracking",
                            "Integration",
                            "PreissuchmaschinenPortale",
                            "Warenwirtschaft",
                            "Versand",
                            "Bezahlung",
                            "StorefrontDetailanpassungen",
                            "Sprache",
                            "Suche",
                            "HeaderFooter",
                            "Detailseite",
                            "MenueKategorien",
                            "Bestellprozess",
                            "KundenkontoPersonalisierung",
                            "Sonderfunktionen",
                            "Themes",
                            "Branche",
                            "Home+Furnishings",
                            "FashionBekleidung",
                            "GartenNatur",
                            "KosmetikGesundheit",
                            "EssenTrinken",
                            "KinderPartyGeschenke",
                            "SportLifestyleReisen",
                            "TechnikIT",
                            "IndustrieGroßhandel",
                            "MigrationTools",
                            "Einkaufswelten",
                            "ConversionOptimierung",
                            "Extensions",
                            "MarketingTools",
                            "B2BExtensions",
                            "Blog",
                            "emailMarketing",
                            "promotionsAndVoucher",
                            "loyalityAndRewards",
                            "recommendations",
                            "otherMarketingCommercials",
                            "socialCommerce",
                            "middlewareAndConnectors",
                            "pim",
                            "dam",
                            "cms",
                            "crm",
                            "personalization"
                        ]
                    }
                },
                "default_locale": {
                    "type": "string",
                    "enum": [
                        "en_GB",
                        "de_DE"
                    ]
                },
                "type": {
                    "type": "string",
                    "description": "Specifies the type of this extension.",
                    "enum": [
                        "extension",
                        "theme"
                    ]
                },
                "automatic_bugfix_version_compatibility": {
                    "type": "boolean",
                    "description": "Specifies whether the extension should automatically be set compatible with Shopware bugfix versions."
                },
                "videos": {
                    "type": "object",
                    "description": "Specifies the links of YouTube-Videos to show or describe the extension.",
                    "additionalProperties": false,
                    "minProperties": 1,
                    "properties": {
                        "de": {
                            "type": "array",
                            "maxItems": 2,
                            "items": {
                                "type": "string"
                            }
                        },
                        "en": {
                            "type": "array",
                            "maxItems": 2,
                            "items": {
                                "type": "string"
                            }
                        }
                    }
                },
                "tags": {
                    "type": "object",
                    "description": "Specifies the tags of the extension.",
                    "additionalProperties": false,
                    "minProperties": 1,
                    "properties": {
                        "de": {
                            "type": "array",
                            "items": {
                                "type": "string"
                            },
                            "maxItems": 5
                        },
                        "en": {
                            "type": "array",
                            "items": {
                                "type": "string"
                            },
                            "maxItems": 5
                        }
                    }
                },
                "highlights": {
                    "type": "object",
                    "description": "Specifies the highlights of the extension.",
                    "additionalProperties": false,
                    "minProperties": 1,
                    "properties": {
                        "de": {
                            "type": "array",
                            "items": {
                                "type": "string"
                            },
                            "maxItems": 5
                        },
                        "en": {
                            "type": "array",
                            "items": {
                                "type": "string"
                            },
                            "maxItems": 5
                        }
                    }
                },
                "features": {
                    "type": "object",
                    "description": "Specifies the features of the extension.",
                    "additionalProperties": false,
                    "minProperties": 1,
                    "properties": {
                        "de": {
                            "type": "array",
                            "items": {
                                "type": "string"
                            },
                            "maxItems": 15
                        },
                        "en": {
                            "type": "array",
                            "items": {
                                "type": "string"
                            },
                            "maxItems": 15
                        }
                    }
                },
                "faq": {
                    "type": "object",
                    "description": "Specifies Frequently Asked Questions for the extension.",
                    "additionalProperties": false,
                    "minProperties": 1,
                    "properties": {
                        "de": {
                            "type": "array",
                            "items": {
                                "$ref": "#/definitions/StoreInfoFaqQuestion"
                            }
                        },
                        "en": {
                            "type": "array",
                            "items": {
                                "$ref": "#/definitions/StoreInfoFaqQuestion"
                            }
                        }
                    }
                },
                "description": {
                    "type": "object",
                    "description": "Specifies the description of the extension in store.",
                    "additionalProperties": false,
                    "minProperties": 1,
                    "properties": {
                        "de": {
                            "type": "string",
                            "description": "Use string or set path to a file with prefix `file:` containing the description, f.e. `file:src/store/manual_de.md`"
                        },
                        "en": {
                            "type": "string",
                            "description": "Use string or set path to a file with prefix `file:` containing the description, f.e. `file:src/store/manual_en.md`"
                        }
                    }
                },
                "installation_manual": {
                    "type": "object",
                    "description": "Installation manual of the extension in store.",
                    "additionalProperties": false,
                    "properties": {
                        "de": {
                            "type": "string",
                            "description": "Use string or set path to a file with prefix `file:` containing the description, f.e. `file:src/store/manual_de.md`"
                        },
                        "en": {
                            "type": "string",
                            "description": "Use string or set path to a file with prefix `file:` containing the description, f.e. `file:src/store/manual_en.md`"
                        }
                    }
                },
                "images": {
                    "type": "array",
                    "description": "Specifies images for the extension in the store.",
                    "minItems": 1,
                    "items": {
                        "type": "object",
                        "required": ["file", "priority"],
                        "additionalProperties": false,
                        "properties": {
                            "file": {
                                "type": "string",
                                "description": "File path to image relative from root of the extension"
                            },
                            "activate": {
                                "type": "object",
                                "description": "Specifies whether the image is active in the language.",
                                "additionalProperties": false,
                                "properties": {
                                    "en": {
                                        "type": "boolean"
                                    },
                                    "de": {
                                        "type": "boolean"
                                    }
                                }
                            },
                            "preview": {
                                "type": "object",
                                "description": "Specifies whether the image is a preview in the language.",
                                "additionalProperties": false,
                                "properties": {
                                    "en": {
                                        "type": "boolean"
                                    },
                                    "de": {
                                        "type": "boolean"
                                    }
                                }
                            },
                            "priority": {
                                "description": "Specifies the order of the image ascending the given priority.",
                                "type": "integer",
                                "minimum": 0
                            }
                        }
                    }
                }
            }
        },
        "StoreInfoFaqQuestion": {
            "type": "object",
            "title": "StoreInfoFaqQuestion",
            "additionalProperties": false,
            "required": [
                "question",
                "answer"
            ],
            "properties": {
                "question": {
                    "type": "string"
                },
                "answer": {
                    "type": "string"
                }
            }
        }
    }
}

{
  "$schema": "http://json-schema.org/draft-04/schema#",
  "additionalProperties": false,
  "definitions": {
    "path": {
      "type": "string",
      "minLength": 1
    },
    "array-of-strings": {
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "array-of-paths": {
      "type": "array",
      "items": {
        "$ref": "#/definitions/path"
      }
    }
  },
  "description": "Configuration Schema for the JavaScript test runner AVA",
  "id": "https://json.schemastore.org/ava.json",
  "properties": {
    "files": {
      "$ref": "#/definitions/array-of-paths",
      "description": "An array of glob patterns to select test files. Files with an underscore prefix are ignored. By default only selects files with `cjs`, `mjs` & `js` extensions, even if the pattern matches other files. Specify `extensions` to allow other file extensions"
    },
    "ignoredByWatcher": {
      "$ref": "#/definitions/array-of-paths",
      "description": "An array of glob patterns to match files that, even if changed, are ignored by the watcher"
    },
    "match": {
      "$ref": "#/definitions/array-of-paths",
      "description": "Not typically useful in the `package.json` configuration, but equivalent to specifying `--match` on the CLI"
    },
    "cache": {
      "type": "boolean",
      "default": true,
      "description": "Defaults to `true` to cache compiled files under `node_modules/.cache/ava.` If `false`, files are cached in a temporary directory instead"
    },
    "concurrency": {
      "type": "number",
      "description": "Max number of test files running at the same time (default: CPU cores)"
    },
    "workerThreads": {
      "type": "boolean",
      "default": true,
      "description": "Use worker threads to run tests (enabled by default). If `false`, tests will run in child processes"
    },
    "failFast": {
      "type": "boolean",
      "default": false,
      "description": "Stop running further tests once a test fails"
    },
    "failWithoutAssertions": {
      "type": "boolean",
      "default": true,
      "description": "If `false`, does not fail a test if it doesn't run assertions"
    },
    "environmentVariables": {
      "title": "environment variables",
      "type": "object",
      "description": "Specifies environment variables to be made available to the tests. The environment variables defined here override the ones from `process.env`",
      "additionalProperties": {
        "type": "string"
      }
    },
    "tap": {
      "type": "boolean",
      "default": false,
      "description": "If `true`, enables the TAP reporter"
    },
    "verbose": {
      "type": "boolean",
      "default": false,
      "description": "If `true`, enables verbose output (though currently non-verbose output is not supported)"
    },
    "snapshotDir": {
      "$ref": "#/definitions/path",
      "description": "Specifies a fixed location for storing snapshot files. Use this if your snapshots are ending up in the wrong location"
    },
    "extensions": {
      "anyOf": [
        {
          "$ref": "#/definitions/array-of-strings"
        },
        {
          "title": "extensions",
          "type": "object",
          "patternProperties": {
            "^(c|m)?js$": {
              "enum": [true]
            }
          },
          "additionalProperties": {
            "enum": ["commonjs", "module"]
          }
        }
      ],
      "default": ["cjs", "mjs", "js"],
      "description": "Extensions of test files. Setting this overrides the default `[\"cjs\", \"mjs\", \"js\"]` value, so make sure to include those extensions in the list. Experimentally you can configure how files are loaded"
    },
    "require": {
      "$ref": "#/definitions/array-of-paths",
      "description": "Extra modules to require before tests are run. Modules are required in the worker processes"
    },
    "timeout": {
      "anyOf": [
        {
          "type": "number",
          "minimum": 0
        },
        {
          "type": "string",
          "pattern": "^(\\d+)(s|m)$"
        }
      ],
      "default": "10s",
      "description": "Timeouts in AVA behave differently than in other test frameworks. AVA resets a timer after each test, forcing tests to quit if no new test results were received within the specified timeout. This can be used to handle stalled tests. See our timeout documentation for more options"
    },
    "nodeArguments": {
      "$ref": "#/definitions/array-of-strings",
      "description": "Configure Node.js arguments used to launch worker processes"
    },
    "utilizeParallelBuilds": {
      "type": "boolean",
      "default": true,
      "description": "If `false`, disable parallel builds (default: `true`)"
    },
    "typescript": {
      "title": "configuration",
      "type": "object",
      "description": "Configures @ava/typescript for projects that precompile TypeScript. Alternatively, you can use `ts-node` to do live testing without transpiling, in which case you shouldn't use the `typescript` property",
      "properties": {
        "extensions": {
          "$ref": "#/definitions/array-of-paths",
          "default": ["ts"],
          "description": "You can configure AVA to recognize additional file extensions as TypeScript (e.g., `[\"ts\", \"tsx\"]` to add partial JSX support). Note that the preserve mode for JSX is not (yet) supported. See also AVA's `extensions` object"
        },
        "rewritePaths": {
          "title": "paths",
          "type": "object",
          "description": "AVA searches your entire project for `*.js`, `*.cjs`, `*.mjs` and `*.ts` files (or other extensions you've configured). It will ignore such files found in the `rewritePaths` targets (e.g. `build/`). If you use more specific paths, for instance `build/main/`, you may need to change AVA's `files` configuration to ignore other directories. Paths are relative to your project directory",
          "patternProperties": {
            "/$": {
              "type": "string",
              "pattern": "/$"
            }
          }
        },
        "compile": {
          "enum": [false, "tsc"],
          "default": false,
          "description": "If `false`, AVA will assume you have already compiled your project. If set to `'tsc'`, AVA will run the TypeScript compiler before running your tests. This can be inefficient when using AVA in watch mode"
        }
      }
    }
  },
  "title": "AVA Config Schema",
  "type": "object"
}

{
  "$schema": "http://json-schema.org/draft-04/schema#",
  "allOf": [
    {
      "$ref": "#/definitions/root-items"
    },
    {
      "type": "object",
      "properties": {
        "env": {
          "$ref": "#/definitions/env-items"
        }
      }
    },
    {
      "$ref": "#/definitions/env-items"
    }
  ],
  "definitions": {
    "root-items": {
      "type": "object",
      "required": ["spec_dir", "spec_files"],
      "properties": {
        "spec_dir": {
          "description": "Spec directory path relative to the current working dir when jasmine is executed.",
          "type": "string",
          "default": ""
        },
        "spec_files": {
          "description": "Array of filepaths (and globs) relative to spec_dir to include and exclude.",
          "type": "array",
          "items": {
            "type": "string"
          },
          "default": []
        },
        "helpers": {
          "description": "Array of filepaths (and globs) relative to spec_dir to include before jasmine specs",
          "type": "array",
          "items": {
            "type": "string"
          },
          "default": []
        }
      }
    },
    "env-items": {
      "description": "Configuration of the Jasmine environment",
      "type": "object",
      "properties": {
        "autoCleanClosure": {
          "description": "Clean closures when a suite is done running (done by clearing the stored function reference). This prevents memory leaks, but you won't be able to run jasmine multiple times.",
          "type": "boolean",
          "default": false
        },
        "failSpecWithNoExpectations": {
          "description": "Whether to fail the spec if it ran no expectations. By default a spec that ran no expectations is reported as passed. Setting this to true will report such spec as a failure.",
          "type": "boolean",
          "default": false
        },
        "hideDisbaled": {
          "description": "Whether or not reporters should hide disabled specs from their output. Currently only supported by Jasmine's HTMLReporter.",
          "type": "boolean",
          "default": false
        },
        "random": {
          "description": "Whether to randomize spec execution order.",
          "type": "boolean",
          "default": true
        },
        "seed": {
          "description": "Seed to use as the basis of randomization. Null causes the seed to be determined randomly at the start of execution.",
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "number"
            },
            {
              "type": "null"
            }
          ],
          "default": null
        },
        "stopOnSpecFailure": {
          "description": "Whether to stop execution of the suite after the first spec failure.",
          "type": "boolean",
          "default": false
        },
        "stopSpecOnExpectationFailure": {
          "description": "Whether to cause specs to only have one expectation failure.",
          "type": "boolean",
          "default": false
        },
        "verboseDeprication": {
          "description": "Whether or not to issue warnings for certain deprecated functionality every time it's used. If not set or set to false, deprecation warnings for methods that tend to be called frequently will be issued only once or otherwise throttled to to prevent the suite output from being flooded with warnings.",
          "type": "boolean",
          "default": false
        }
      }
    }
  },
  "id": "https://json.schemastore.org/jasmine.json",
  "title": "Schema for jasmine JSON config file"
}

