          },
          "requests": {
            "$ref": "#/definitions/requests"
          },
          "socket": {
            "$ref": "#/definitions/socket"
          },
          "incidentThreshold": {
            "$ref": "#/definitions/incidentThreshold"
          },
          "recoveryThreshold": {
            "$ref": "#/definitions/recoveryThreshold"
          },
          "alerts": {
            "$ref": "#/definitions/alerts"
          }
        }
      }
    },
    "notifications": {
