{
  "$id": "https://json.schemastore.org/pgap_yaml_input_reader",
  "$schema": "http://json-schema.org/draft-07/schema#",
  "additionalProperties": false,
  "definitions": {},
  "description": "NCBI Prokaryotic Genome Annotation Pipeline (PGAP) input metadata (submol) JSON/YAML configuration file",
  "properties": {
    "$schema": {
      "$id": "/$schema",
      "type": "string",
      "title": "Schema",
      "description": "The value of this keyword MUST be a URI (containing a scheme) and this URI MUST be normalized. ",
      "default": "",
      "examples": ["https://json.schemastore.org/pgap_yaml_input_reader"]
    },
    "consortium": {
      "$id": "/properties/consortium",
      "type": "string",
      "title": "Consortium",
      "description": "Name of the project that generated the genome assembly",
      "default": "",
      "examples": ["SkyNet"]
    },
    "comment": {
      "$id": "/properties/comment",
      "type": "string",
      "title": "Free text comment about the genome assembly",
      "description": "Appears in the COMMENT section of each GenBank sequence record.",
      "default": "",
      "examples": [
        "This draft WGS assembly was generated by running SKESA to generate a de-novo assembly. The de-novo assembly was then concatenated with  configs generated using a guided assembler using antimicrobial resistance genes as baits to comprehensively catalog the set of resistance genes in the isolate. Note, some parts of the configs derived from the guided assembler may overlap de-novo configs, and other guided assembler configs. De-novo configs can be differentiated from guided assembler configs by their names, which include either 'denovo' or 'guided'."
      ]
    },
    "tp_assembly": {
      "$id": "/properties/tp_assembly",
      "type": "boolean",
      "title": "Reserved",
      "description": "NCBI internal flag used for testing.",
      "default": false,
      "examples": [false]
    },
    "sra": {
      "$id": "/properties/sra",
      "type": "array",
      "title": "SRA assembly data",
      "description": "Sequence reads used to build the assembly",
      "items": {
        "$id": "/properties/sra/items",
        "type": "object",
        "additionalProperties": false,
        "required": ["accession"],
        "properties": {
          "accession": {
            "$id": "/properties/sra/items/properties/accession",
            "type": "string",
            "title": "SRA Accession",
            "description": "Sequence Read Archive (SRA) accession for the run (with SRR, ERR or DRR prefix)",
            "default": "",
            "examples": ["SRR8796989"]
          }
        }
      }
    },
    "authors": {
      "$id": "/properties/authors",
      "type": "array",
      "title": "Author(s) of the genome assembly",
      "description": "Optional, but include if intending to submit to GenBank. Authors can be different from the contact.",
      "items": {
        "$id": "/properties/authors/items",
        "type": "object",
        "additionalProperties": false,
        "required": ["author"],
        "properties": {
          "author": {
            "$id": "/properties/authors/items/properties/author",
            "type": "object",
            "additionalProperties": false,
            "required": ["first_name", "last_name"],
            "properties": {
              "first_name": {
                "$id": "/properties/authors/items/properties/author/properties/first_name",
                "type": "string",
                "title": "First name",
                "default": "",
                "examples": ["Arnold"]
              },
              "last_name": {
                "$id": "/properties/authors/items/properties/author/properties/last_name",
                "type": "string",
                "title": "Last name",
                "default": "",
                "examples": ["Schwarzenegger"]
              },
              "middle_initial": {
                "$id": "/properties/authors/items/properties/author/properties/middle_initial",
                "type": "string",
                "title": "First letter of middle name",
                "default": "",
                "examples": ["T800"]
              }
            }
          }
        }
      }
    },
    "bioproject": {
      "$id": "/properties/bioproject",
      "type": "string",
      "title": "BioProject ID (PRJXX) for the project, if available",
      "default": "",
      "examples": ["PRJ9999999"]
    },
    "biosample": {
      "$id": "/properties/biosample",
      "type": "string",
      "title": "BioSample ID (SAMXXX) for the sequenced sample, if available",
      "default": "",
      "examples": ["SAMN99999999"]
    },
    "contact_info": {
      "$id": "/properties/contact_info",
      "type": "object",
      "title": "Submitter contact information",
      "description": "Optional, but include if intending to submit to GenBank. The main contact for this genome assembly.",
      "additionalProperties": false,
      "required": [
        "organization",
        "department",
        "city",
        "country",
        "street",
        "email",
        "first_name",
        "last_name",
        "postal_code"
      ],
      "properties": {
        "state": {
          "$id": "/properties/contact_info/properties/state",
          "type": "string",
          "title": "State or region",
          "default": "",
          "examples": ["MD", "Florida"]
        },
        "fax": {
          "$id": "/properties/contact_info/properties/fax",
          "type": "string",
          "title": "Fax number",
          "default": "",
          "examples": ["301-555-1234", "+7 095 555 1234"]
        },
        "city": {
          "$id": "/properties/contact_info/properties/city",
          "type": "string",
          "title": "City",
          "default": "",
          "examples": ["Docker"]
        },
        "country": {
          "$id": "/properties/contact_info/properties/country",
          "type": "string",
          "title": "Country",
          "default": "",
          "examples": ["Lappland"]
        },
        "department": {
          "$id": "/properties/contact_info/properties/department",
          "type": "string",
          "title": "Department or division submitting the genome assembly",
          "default": "",
          "examples": ["Department of Using NCBI"]
        },
        "email": {
          "$id": "/properties/contact_info/properties/email",
          "type": "string",
          "title": "Email address",
          "default": "",
          "examples": ["jane_doe@gmail.com"]
        },
        "first_name": {
          "$id": "/properties/contact_info/properties/first_name",
          "type": "string",
          "title": "First name",
          "default": "",
          "examples": ["Jane"]
        },
        "middle_initial": {
          "$id": "/properties/contact_info/properties/middle_initial",
          "type": "string",
          "title": "First letter of middle name",
          "default": "",
          "examples": ["N"]
        },
        "last_name": {
          "$id": "/properties/contact_info/properties/last_name",
          "type": "string",
          "title": "Last name",
          "default": "",
          "examples": ["Doe"]
        },
        "organization": {
          "$id": "/properties/contact_info/properties/organization",
          "type": "string",
          "title": "Organization or consortium submitting the genome assembly",
          "default": "",
          "examples": ["Institute of Klebsiella foobarensis research"]
        },
        "phone": {
          "$id": "/properties/contact_info/properties/phone",
          "type": "string",
          "title": "Phone number",
          "default": "",
          "examples": ["301-555-0245"]
        },
        "postal_code": {
          "$id": "/properties/contact_info/properties/postal_code",
          "type": "string",
          "title": "Postal code",
          "default": "",
          "examples": ["12345"]
        },
        "street": {
          "$id": "/properties/contact_info/properties/street",
          "type": "string",
          "title": "Street address",
          "default": "",
          "examples": ["1234 Main St"]
        }
      }
    },
    "fasta": {
      "$id": "/properties/fasta",
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "class": {
          "$id": "/properties/fasta/properties/class",
          "type": "string",
          "title": "Class of input type",
          "default": "",
          "examples": ["File"]
        },
        "location": {
          "$id": "/properties/fasta/properties/location",
          "type": "string",
          "title": "Location of input file",
          "default": "",
          "examples": ["sample_fasta_input.fasta"]
        }
      }
    },
    "locus_tag_prefix": {
      "$id": "/properties/locus_tag_prefix",
      "type": "string",
      "title": "Locus tag prefix",
      "description": "One to 9-letter prefix to use for naming genes on this genome assembly. If an official locus tag prefix was already reserved from an INSDC organization (GenBank, ENA or DDBJ) for the given BioSample and BioProject pair, provide here. Otherwise, provide a string of your choice. If no value is provided, the prefix 'pgaptmp' will be used. See more details in this Note about locus tags at: https://github.com/ncbi/pgap/wiki/Input-Files#Note-about-locus-tags",
      "default": "",
      "examples": ["tmp"]
    },
    "organism": {
      "$id": "/properties/organism",
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "strain": {
          "$id": "/properties/organism/properties/strain",
          "type": "string",
          "title": "Strain",
          "description": "Strain of the sequenced organism",
          "default": "",
          "examples": ["my_strain"]
        },
        "genus_species": {
          "$id": "/properties/organism/properties/genus_species",
          "type": "string",
          "title": "Genus and species",
          "description": "Binomial name or, if the species is unknown, genus for the sequenced organism. This identifier must be valid in NCBI Taxonomy. See Taxonomy information for how to find out if the name is valid: https://github.com/ncbi/pgap/wiki/Input-Files#Taxonomy-information",
          "default": "",
          "examples": ["Escherichia coli"]
        }
      }
    },
    "publications": {
      "$id": "/properties/publications",
      "type": "array",
      "title": "Publication describing the genome assembly",
      "items": {
        "$id": "/properties/publications/items",
        "type": "object",
        "additionalProperties": false,
        "required": ["publication"],
        "properties": {
          "publication": {
            "$id": "/properties/publications/items/properties/publication",
            "type": "object",
            "additionalProperties": false,
            "properties": {
              "authors": {
                "$id": "/properties/publications/items/properties/publication/properties/authors",
                "title": "Author(s)",
                "type": "array",
                "items": {
                  "$id": "/properties/publications/items/properties/publication/properties/authors/items",
                  "type": "object",
                  "additionalProperties": false,
                  "properties": {
                    "author": {
                      "$id": "/properties/publications/items/properties/publication/properties/authors/items/properties/author",
                      "type": "object",
                      "additionalProperties": false,
                      "required": ["first_name", "last_name"],
                      "properties": {
                        "first_name": {
                          "$id": "/properties/publications/items/properties/publication/properties/authors/items/properties/author/properties/first_name",
                          "type": "string",
                          "title": "First name",
                          "default": "",
                          "examples": ["Arnold"]
                        },
                        "last_name": {
                          "$id": "/properties/publications/items/properties/publication/properties/authors/items/properties/author/properties/last_name",
                          "type": "string",
                          "title": "Last name",
                          "default": "",
                          "examples": ["Schwarzenegger"]
                        },
                        "middle_initial": {
                          "$id": "/properties/publications/items/properties/publication/properties/authors/items/properties/author/properties/middle_initial",
                          "type": "string",
                          "title": "First letter of middle name",
                          "default": "",
                          "examples": ["T800"]
                        }
                      }
                    }
                  }
                }
              },
              "status": {
                "$id": "/properties/publications/items/properties/publication/properties/status",
                "type": "string",
                "title": "Publication status",
                "description": "Can be only one of: published, in-press, unpublished",
                "default": "",
                "enum": ["published", "in-press", "unpublished"]
              },
              "pmid": {
                "$id": "/properties/publications/items/properties/publication/properties/pmid",
                "type": "integer",
                "title": "PubMed ID for the publication",
                "default": ""
              },
              "title": {
                "$id": "/properties/publications/items/properties/publication/properties/title",
                "type": "string",
                "title": "Title",
                "default": "",
                "examples": [
                  "Discrete CHARMm of Klebsiella foobarensis. Journal of Improbable Results, vol. 34, issue 13, pages: 10001-100005, 2018"
                ]
              }
            }
          }
        }
      }
    },
    "topology": {
      "$id": "/properties/topology",
      "type": "string",
      "title": "Topology of the sequences included in the fasta file",
      "description": "Possible values are linear or circular. Circular means that the first base in the sequence is adjacent to the last base. Please provide the topology in the metadata YAML file only if it is applicable to ALL sequences in the fasta file. If some sequences in the assembled genome are circular and others linear, include the topology in the definition line of each sequence in the fasta file with the tag value pair [topology=circular] or [topology=linear], after the SeqID and a space (e.g. >seq1 [topology=circular]). If the topology is provided in neither the metadata YAML nor the fasta file, the sequences will be presumed to be linear.",
      "default": "",
      "examples": ["circular", "linear"]
    },
    "location": {
      "$id": "/properties/location",
      "type": "string",
      "title": "Location of the sequences included in the fasta file",
      "description": "Possible values are chromosome or plasmid. Please provide the location in the metadata YAML file only if it is applicable to ALL sequences in the fasta file. If some sequences in the assembled genome are chromosomes and others plasmids, include the location in the definition line of each sequence in the fasta file with the tag value pair [location=chromosome] or [location=plasmid], after the SeqID and a space (e.g. >seq1 [location=plasmid]). In plasmid case add [plasmid-name=<plasmidname>]. If the location is provided in neither the metadata YAML nor the fasta file, the sequences will be presumed to be chromosome. Note: since 2021 releases of PGAPx this will affect noticeably the annotation on the molecule",
      "default": "",
      "examples": ["chromosome", "plasmid"]
    }
  },
  "required": ["authors", "contact_info"],
  "title": "NCBI PGAP submol YAML",
  "type": "object"
}

{
  "$id": "https://json.schemastore.org/sourcehut-build-0.65.0.json",
  "$schema": "http://json-schema.org/draft-07/schema#",
  "description": "A recipe for Sourcehut CI service. For details, see https://man.sr.ht/builds.sr.ht/manifest.md.",
  "properties": {
    "image": {
      "description": "Which OS image to build in. A list of available build images can be found at https://man.sr.ht/builds.sr.ht/compatibility.md",
      "type": "string",
      "examples": ["archlinux", "alpine/latest"]
    },
    "arch": {
      "description": "Which architecture to build for. See https://man.sr.ht/builds.sr.ht/compatibility.md for a list of available architectures.",
      "type": "string",
      "examples": ["aarch64", "x86_64"]
    },
    "packages": {
      "description": "A list of packages to install on the image. For image-specific details, consult https://man.sr.ht/builds.sr.ht/compatibility.md",
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "repositories": {
      "description": "A list of extra repositories to enable with the image's package manager. The specific format varies by base image, consult https://man.sr.ht/builds.sr.ht/compatibility.md for details.",
      "type": "object",
      "additionalProperties": {
        "type": "string"
      }
    },
    "artifacts": {
      "description": "A list of files to extract from the completed build environment and make available for downloading from the jobs page. Artifacts are only uploaded for successful jobs and are pruned after 90 days. \nNote that the file names are interpreted literally: do not use ~ or any shell code. If a relative path is used (e.g. example/my-artifact.tar.gz), it will be interpreted relative to the build user's home directory.",
      "type": "array",
      "items": {
        "type": "string"
      },
      "examples": ["example/my-artifact.tar.gz"]
    },
    "shell": {
      "description": "Whether to keep the build VM alive after all of the tasks have finished, even if it doesn't fail, so you can SSH in. You can also SSH in before the tasks have finished and tail the output of the build in your terminal. Learn more at https://man.sr.ht/builds.sr.ht/build-ssh.md",
      "type": "boolean"
    },
    "sources": {
      "description": "A list of repositories to clone into the home directory of the build user in the build environment. Optionally, prefix the protocol with the source control management scheme, to specify a protocol other than git. To specify a non-default git revision, append #commit-object to the repository.",
      "type": "array",
      "items": {
        "type": "string",
        "examples": [
          "https://git.sr.ht/~sircmpwn/scdoc",
          "https://git.sr.ht/~sircmpwn/scdoc#devel",
          "git@git.sr.ht:~sircmpwn/scdoc",
          "hg+https://hg.sr.ht/~sircmpwn/scdoc",
          "hg+ssh://hg.sr.ht/~sircmpwn/scdoc"
        ]
      }
    },
    "tasks": {
      "description": "A list of scripts to execute in the build environment. \nTask names must use only lowercase alphanumeric characters, underscores or dashes and must be <=128 characters in length. Tasks are executed in the order specified. \nEach task is run in a separate login session, so if you modify the groups of the build user they will be effective starting from the subsequent task.",
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "additionalProperties": {
          "type": "string"
        },
        "propertyNames": {
          "pattern": "^[a-z0-9_-]{1,128}$"
        },
        "examples": [
          {
            "package": "cd $site\ntar -cvz . > ../site.tar.gz"
          }
        ]
      }
    },
    "triggers": {
      "description": "A list of triggers to execute post-build, which can be used to send emails or do other post-build tasks. \nLearn more at https://man.sr.ht/builds.sr.ht/triggers.md",
      "type": "array",
      "items": {
        "type": "object",
        "additionalProperties": true,
        "properties": {
          "action": {
            "description": "Trigger type",
            "type": "string",
            "enum": ["email", "webhook"]
          },
          "condition": {
            "description": "When to execute this trigger",
            "type": "string",
            "enum": ["always", "failure", "success"]
          }
        },
        "required": ["action", "condition"]
      }
    },
    "environment": {
      "description": "A list of key/value pairs for options to set in the build environment via ~/.buildenv",
      "type": "object",
      "additionalProperties": {
        "type": "string"
      },
      "examples": [
        {
          "site": "your-username.srht.site"
        }
      ]
    },
    "secrets": {
      "description": "List of secret UUIDs to be added to the guest during the build. Learn more at https://man.sr.ht/builds.sr.ht/#secrets",
      "type": "array",
      "items": {
        "type": "string",
        "examples": ["46f739e5-4538-45dd-a79f-bf173b7a2ed9"]
      }
    },
    "oauth": {
      "description": "If present, and secrets are enabled for this build, an OAuth 2.0 bearer token is generated for this build with the given string as the list of grants. The acurl command may be used in the task scripts to perform authenticated GraphAL API requests (https://man.sr.ht/graphql.md).",
      "type": "string",
      "examples": ["pages.sr.ht/PAGES:RW"]
    }
  },
  "required": ["image", "tasks"],
  "title": "Sourcehut Build Manifest",
  "type": "object"
}

