        },
        "shared-node-browser": {
          "type": "boolean",
          "description": "Globals common to both Node and Browser"
        },
        "embertest": {
          "type": "boolean",
          "description": "Ember test helper globals"
        },
        "es6": {
          "type": "boolean",
          "description": "enable all ECMAScript 6 features except for modules"
        },
        "greasemonkey": {
          "type": "boolean",
