        },
        "worker": {
          "type": "boolean",
          "description": "web workers global variables"
        }
      }
    },
    "extends": {
      "description": "If you want to extend a specific configuration file, you can use the extends property and specify the path to the file. The path can be either relative or absolute.",
      "$ref": "#/definitions/stringOrStringArray"
    },
    "globals": {
      "description": "Set each global variable name equal to true to allow the variable to be overwritten or false to disallow overwriting.",
      "type": "object",
      "additionalProperties": {
        "oneOf": [
          {
            "type": "string",
            "enum": ["readonly", "writable", "off"]
          },
          {
            "description": "The values false|\"readable\" and true|\"writeable\" are deprecated, they are equivalent to \"readonly\" and \"writable\", respectively.",
            "type": "boolean"
          }
        ]
      }
    },
    "noInlineConfig": {
      "description": "Prevent comments from changing config or rules",
      "type": "boolean"
    },
    "parser": {
      "type": "string"
    },
    "parserOptions": {
      "description": "The JavaScript language options to be supported",
      "type": "object",
      "properties": {
        "ecmaFeatures": {
          "$ref": "#/properties/ecmaFeatures"
        },
        "ecmaVersion": {
          "enum": [
            3,
            5,
            6,
            2015,
            7,
            2016,
            8,
            2017,
            9,
            2018,
            10,
            2019,
            11,
            2020,
            12,
            2021,
            13,
            2022,
            14,
            2023,
            "latest"
          ],
          "default": 11,
          "description": "Set to 3, 5, 6, 7, 8, 9, 10, 11 (default), 12, 13, 14 or \"latest\" to specify the version of ECMAScript syntax you want to use. You can also set to 2015 (same as 6), 2016 (same as 7), 2017 (same as 8), 2018 (same as 9), 2019 (same as 10), 2020 (same as 11), 2021 (same as 12), 2022 (same as 13) or 2023 (same as 14) to use the year-based naming. \"latest\" always enables the latest supported ECMAScript version."
        },
        "sourceType": {
          "enum": ["script", "module"],
          "default": "script",
          "description": "set to \"script\" (default) or \"module\" if your code is in ECMAScript modules"
        }
      }
    },
    "plugins": {
      "description": "ESLint supports the use of third-party plugins. Before using the plugin, you have to install it using npm.",
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "root": {
      "description": "By default, ESLint will look for configuration files in all parent folders up to the root directory. This can be useful if you want all of your projects to follow a certain convention, but can sometimes lead to unexpected results. To limit ESLint to a specific project, set this to `true` in a configuration in the root of your project.",
      "type": "boolean"
    },
    "ignorePatterns": {
      "description": "Tell ESLint to ignore specific files and directories. Each value uses the same pattern as the `.eslintignore` file.",
      "$ref": "#/definitions/stringOrStringArray"
    },
    "rules": {
      "description": "ESLint comes with a large number of rules. You can modify which rules your project uses either using configuration comments or configuration files.",
      "type": "object",
      "allOf": [
        {
          "$ref": "#/definitions/possibleErrors"
        },
        {
          "$ref": "#/definitions/bestPractices"
        },
        {
          "$ref": "#/definitions/strictMode"
        },
        {
          "$ref": "#/definitions/variables"
        },
        {
          "$ref": "#/definitions/nodeAndCommonJs"
        },
        {
          "$ref": "#/definitions/stylisticIssues"
        },
        {
          "$ref": "#/definitions/ecmaScript6"
        },
        {
          "$ref": "#/definitions/legacy"
        }
      ]
    },
    "settings": {
      "description": "ESLint supports adding shared settings into configuration file. You can add settings object to ESLint configuration file and it will be supplied to every rule that will be executed. This may be useful if you are adding custom rules and want them to have access to the same information and be easily configurable.",
      "type": "object"
    },
    "overrides": {
      "type": "array",
      "description": "Allows to override configuration for files and folders, specified by glob patterns",
      "items": {
        "type": "object",
        "properties": {
          "files": {
            "description": "Glob pattern for files to apply 'overrides' configuration, relative to the directory of the config file",
            "oneOf": [
              {
                "type": "string"
              },
              {
                "minItems": 1,
                "type": "array",
                "items": {
                  "type": "string"
                }
              }
            ]
          },
          "extends": {
            "description": "If you want to extend a specific configuration file, you can use the extends property and specify the path to the file. The path can be either relative or absolute.",
            "$ref": "#/definitions/stringOrStringArray"
          },
          "excludedFiles": {
            "description": "If a file matches any of the 'excludedFiles' glob patterns, the 'overrides' configuration won't apply",
            "$ref": "#/definitions/stringOrStringArray"
          },
          "ecmaFeatures": {
            "$ref": "#/properties/ecmaFeatures"
          },
          "env": {
            "$ref": "#/properties/env"
          },
          "globals": {
            "$ref": "#/properties/globals"
          },
          "parser": {
            "$ref": "#/properties/parser"
          },
          "parserOptions": {
            "$ref": "#/properties/parserOptions"
          },
          "plugins": {
            "$ref": "#/properties/plugins"
          },
          "processor": {
            "description": "To specify a processor, specify the plugin name and processor name joined by a forward slash",
            "type": "string"
          },
          "rules": {
            "$ref": "#/properties/rules"
          },
          "settings": {
            "$ref": "#/properties/settings"
          },
          "overrides": {
            "$ref": "#/properties/overrides"
          }
        },
        "additionalProperties": false,
        "required": ["files"]
      }
    }
  },
  "title": "JSON schema for ESLint configuration files",
  "type": "object"
}

{
  "$id": "https://json.schemastore.org/prometheus.rules.test.json",
  "$schema": "http://json-schema.org/draft-07/schema#",
  "additionalProperties": false,
  "definitions": {
    "alert": {
      "properties": {
        "exp_annotations": {
          "$ref": "#/definitions/labels",
          "description": "Expanded annotations of the expected alert"
        },
        "exp_labels": {
          "$ref": "#/definitions/labels",
          "description": "Expanded labels and annotations of the expected alert. This also include the labels of the sample associated with the alert (same as what you see in `/alerts`, without series `__name__` and `alertname`)."
        }
      },
      "required": ["exp_labels"],
      "type": "object"
    },
    "alert_test_case": {
      "additionalProperties": false,
      "properties": {
        "alertname": {
          "description": "Name of the alert to be tested.",
          "type": "string"
        },
        "eval_time": {
          "$ref": "#/definitions/duration",
          "description": "The time elapsed from time=0s when the alerts have to be checked."
        },
        "exp_alerts": {
          "description": "List of expected alerts firing under the given alertname at the given evaluation time",
          "items": {
            "$ref": "#/definitions/alert"
          },
          "type": "array"
        }
      },
      "required": ["eval_time", "alertname"],
      "type": "object"
    },
    "duration": {
      "minLength": 1,
      "pattern": "^([0-9]+y)?([0-9]+w)?([0-9]+d)?([0-9]+h)?([0-9]+m)?([0-9]+s)?([0-9]+ms)?$",
      "type": ["string", "null"]
    },
    "label_value": {
      "type": "string"
    },
    "labels": {
      "additionalProperties": false,
      "patternProperties": {
        "^[a-zA-Z_][a-zA-Z0-9_]*$": {
          "$ref": "#/definitions/label_value"
        }
      },
      "type": ["object", "null"]
    },
    "promql_test_case": {
      "additionalProperties": false,
      "properties": {
        "eval_time": {
          "$ref": "#/definitions/duration",
          "description": "The time elapsed from time=0s when the expression has to be evaluated."
        },
        "exp_samples": {
          "description": "Expected samples at the given evaluation time.",
          "items": {
            "$ref": "#/definitions/sample"
          },
          "type": "array"
        },
        "expr": {
          "description": "PromQL expression to evaluate",
          "type": "string"
        }
      },
      "required": ["expr", "eval_time"],
      "type": "object"
    },
    "sample": {
      "properties": {
        "labels": {
          "description": "Labels of the sample in the usual series notation '<metric name>{<label name>=<label value>, ...}'",
          "type": "string"
        },
        "value": {
          "description": "Expected value of the PromQL expression.",
          "type": "number"
        }
      },
      "required": ["labels", "value"],
      "type": "object"
    },
    "series": {
      "additionalProperties": false,
      "properties": {
        "series": {
          "description": "This follows the usual series notation '<metric name>{<label name>=<label value>, ...}'.",
          "type": "string"
        },
        "values": {
          "description": "This uses expanded notation to project time series. There are also the special `_` and `stale` values to indicate missing or stale samples",
          "type": "string"
        }
      },
      "required": ["series", "values"],
      "type": "object"
    },
    "test_group": {
      "additionalProperties": false,
      "properties": {
        "alert_rule_test": {
          "description": "Unit tests for alerting rules. We only consider the alerting rules from the input files.",
          "items": {
            "$ref": "#/definitions/alert_test_case"
          },
          "type": "array"
        },
        "external_labels": {
          "$ref": "#/definitions/labels",
          "description": "External labels accessible to the alert template."
        },
        "external_url": {
          "description": "External URL accessible to the alert template. Usually set using --web.external-url.",
          "type": "string"
        },
        "input_series": {
          "description": "A list of time series",
          "items": {
            "$ref": "#/definitions/series"
          },
          "type": "array"
        },
        "interval": {
          "$ref": "#/definitions/duration",
          "description": "The time elapsed from time=0s when the alerts have to be checked."
        },
        "name": {
          "description": "Name of the test group",
          "type": "string"
        },
        "promql_expr_test": {
          "description": "Unit tests for PromQL expressions",
          "items": {
            "$ref": "#/definitions/promql_test_case"
          },
          "type": "array"
        }
      },
      "required": ["interval", "input_series"],
      "type": "object"
    }
  },
  "description": "Prometheus rules test file. See https://prometheus.io/docs/prometheus/latest/configuration/unit_testing_rules/ for details.",
  "properties": {
    "evaluation_interval": {
      "default": "1m",
      "description": "The evaluation interval for the tests. [duration] format.",
      "type": ["string", "null"]
    },
    "group_eval_order": {
      "description": "The order in which group names are listed below will be the order of evaluation of rule groups (at a given evaluation time).",
      "items": {
        "type": "string"
      },
      "type": ["array", "null"]
    },
    "rule_files": {
      "description": "List of rule files to consider for testing. Globs are supported.",
      "items": {
        "type": "string"
      },
      "type": "array"
    },
    "tests": {
      "items": {
        "$ref": "#/definitions/test_group",
        "description": "All the tests are listed here."
      },
      "type": "array"
    }
  },
  "title": "Prometheus Rules Test File",
  "type": "object"
}

{
  "$id": "https://json.schemastore.org/nodemon.json",
  "$schema": "http://json-schema.org/draft-07/schema#",
  "definitions": {
    "pathPattern": {
      "anyOf": [
        {
          "type": "string"
        },
        {
          "type": "object",
          "properties": {
            "re": {
              "type": "string"
            }
          },
          "additionalProperties": false,
          "required": ["re"],
          "description": "Regular expression"
        }
      ]
    },
    "terminationSignals": {
      "anyOf": [
        {
          "const": "SIGTERM"
        },
        {
          "const": "SIGINT"
        },
        {
          "const": "SIGQUIT"
        },
        {
          "const": "SIGKILL"
        },
        {
          "const": "SIGHUP"
        }
      ]
    },
    "variables": {
      "anyOf": [
        {
          "const": "{{pwd}}",
          "description": "The current directory"
        },
        {
          "const": "{{filename}}",
          "description": "The filename you pass to nodemon"
        }
      ]
    }
  },
  "dependencies": {
    "pollingInterval": {
      "required": ["legacyWatch"]
    },
    "nodeArgs": {
      "exec": {
        "const": "node"
      },
      "required": ["exec"]
    }
  },
  "properties": {
    "colours": {
      "default": true,
      "description": "set to false to disable color output",
      "type": "boolean"
    },
    "cwd": {
      "description": "change into <dir> before running the script",
      "type": "string"
    },
    "delay": {
      "default": 0,
      "description": "debounce restart for a number of milliseconds",
      "type": "number"
    },
    "dump": {
      "default": false,
      "description": "print full debug configuration",
      "type": "boolean"
    },
    "exec": {
      "description": "execute script with \"app\", ie. -x \"python -v\".  May use variables.",
      "examples": ["{{pwd}}/index.js --some-arg", "{{filename}}"],
      "format": "<app> <your args>",
      "type": "string"
    },
    "execMap": {
      "description": "The global config file is useful for setting up default executables",
      "type": "object"
    },
    "exitcrash": {
      "description": "Exit nodemon after crash",
      "type": "boolean"
    },
    "ext": {
      "default": "*",
      "description": "extensions to look for, ie. \"js,jade,hbs\"",
      "type": "string"
    },
    "ignore": {
      "description": "Ignore directory or file.  One entry per ignored value.  Wildcards are allowed.",
      "items": {
        "$ref": "#/definitions/pathPattern",
        "description": "Path or pattern of file or directory to ignore.  Can also use regular expressions wrapped in an object with a single property named \"re\".",
        "examples": [
          ".gitignore",
          ".vscode",
          "__tests__/*",
          "__*__/*.js",
          "*.test.js"
        ]
      },
      "type": "array"
    },
    "ignoreRoot": {
      "description": "root paths to ignore",
      "items": {
        "type": "string"
      },
      "type": "array"
    },
    "legacyWatch": {
      "default": false,
      "description": "use polling to watch for changes (typically needed when watching over a network/Docker)",
      "type": "boolean"
    },
    "noUpdateNotifier": {
      "default": false,
      "description": "opt-out of update version check",
      "type": "boolean"
    },
    "nodeArgs": {
      "description": "arguments to pass to node if exec is \"node\"",
      "type": "array"
    },
    "pollingInterval": {
      "default": 100,
      "description": "combined with legacyWatch, milliseconds to poll for (default 100)",
      "type": "number"
    },
    "quiet": {
      "default": false,
      "description": "minimise nodemon messages to start/stop only",
      "type": "boolean"
    },
    "runOnChangeOnly": {
      "default": false,
      "description": "execute script on change only, not startup",
      "type": "boolean"
    },
    "signal": {
      "$ref": "#/definitions/terminationSignals",
      "description": "use specified kill signal instead of default (ex. SIGTERM)",
      "type": "string"
    },
    "spawn": {
      "default": false,
      "description": "force nodemon to use spawn (over fork) [node only]",
      "type": "boolean"
    },
    "stdin": {
      "default": true,
      "description": "set to false to have nodemon pass stdin directly to child process",
      "type": "boolean"
    },
    "verbose": {
      "default": false,
      "description": "show detail on what is causing restarts",
      "type": "boolean"
    },
    "watch": {
      "description": "Watch directory or file.  One entry per watched value.  Wildcards are allowed.",
      "items": {
        "$ref": "#/definitions/pathPattern",
        "description": "Path or pattern of file or directory to watch.  Can also use regular expressions wrapped in an object with a single property named \"re\".",
        "examples": ["src/index.js", "src", "src/*.js", "*.js"]
      },
      "type": "array"
    }
  },
  "title": "JSON Schema for Nodemon Config",
  "type": "object"
}

{
  "$id": "https://json.schemastore.org/paper-plugin",
  "$schema": "http://json-schema.org/draft-07/schema#",
  "additionalProperties": true,
  "definitions": {
    "plugin-name": {
      "type": "string",
      "pattern": "^[A-Za-z0-9_\\.-]+$"
    },
    "plugin-class": {
      "type": "string",
      "pattern": "^(?!io\\.papermc\\.)([a-zA-Z_$][a-zA-Z\\d_$]*\\.)*[a-zA-Z_$][a-zA-Z\\d_$]*$"
    },
    "perm-default": {
      "enum": ["true", "false", "op", "notop"]
    },
    "permission": {
      "type": "object",
      "description": "A permission for this plugin",
      "properties": {
        "default": {
          "$ref": "#/definitions/perm-default",
          "description": "Default for this permission"
        },
        "description": {
          "type": "string"
        },
        "children": {
          "oneOf": [
            {
              "type": "array",
              "items": {
                "type": "string"
              }
            },
            {
              "type": "object",
              "additionalProperties": {
                "oneOf": [
                  {
                    "type": "boolean",
                    "description": "False to not inherit the parent permission."
                  },
                  {
                    "$ref": "#/definitions/permission"
                  }
                ]
              }
            }
          ]
        }
      },
      "additionalProperties": false
    },
    "dependency": {
      "description": "A plugin dependency",
      "type": "object",
      "properties": {
        "load": {
          "description": "Where to load this dependency in relation to the plugin. Defaults to OMIT",
          "enum": ["AFTER", "BEFORE", "OMIT"]
        },
        "join-classpath": {
          "description": "Whether this dependency's classpath should be joined by the plugin. Defaults to true",
          "type": "boolean"
        },
        "required": {
          "description": "Whether this dependency is required for the plugin to load. Defaults to true",
          "type": "boolean"
        }
      },
      "additionalProperties": false
    },
    "dependency-group": {
      "type": "object",
      "additionalProperties": {
        "$ref": "#/definitions/dependency"
      }
    }
  },
  "description": "JSON schema for Paper Plugin YAML",
  "properties": {
    "name": {
      "description": "The name of the plugin",
      "$ref": "#/definitions/plugin-name"
    },
    "main": {
      "description": "The main class of the plugin",
      "examples": ["com.example.ExamplePlugin"],
      "$ref": "#/definitions/plugin-class"
    },
    "bootstrapper": {
      "description": "The main class of the custom bootstrapper for the plugin",
      "examples": ["com.example.ExamplePluginBoostrapper"],
      "$ref": "#/definitions/plugin-class"
    },
    "loader": {
      "description": "The main class of the custom plugin loader for the plugin",
      "examples": ["com.example.ExamplePluginLoader"],
      "$ref": "#/definitions/plugin-class"
    },
    "provides": {
      "description": "Satisfies dependency requirements as this plugin. When resolving dependencies, if a plugin requires a plugin in this list, this plugin will satisfy it.",
      "type": "array",
      "uniqueItems": true,
      "items": {
        "$ref": "#/definitions/plugin-name"
      }
    },
    "has-open-classloader": {
      "type": "boolean",
      "description": "Whether the plugin should have its classloader public to other paper plugins"
    },
    "version": {
      "description": "The version of the plugin",
      "type": ["string"]
    },
    "description": {
      "description": "The description of the plugin",
      "type": "string"
    },
    "authors": {
      "type": "array",
      "description": "Main authors of the plugin",
      "items": {
        "type": "string",
        "uniqueItems": true
      }
    },
    "contributors": {
      "type": "array",
      "description": "Other contributors to the plugin",
