{
  "$id": "https://json.schemastore.org/vim-addon-info",
  "$schema": "http://json-schema.org/draft-07/schema#",
  "definitions": {
    "url": {
      "type": "string",
      "format": "uri",
      "examples": ["git://github.com/tpope/vim-surround"]
    },
    "repoType": {
      "enum": ["hg", "git", "svn", "bzr"]
    },
    "selfRepository": {
      "description": "Info for the plugin itself. Describes where the canonical copy of the plugin can be fetched from.",
      "type": "object",
      "properties": {
        "type": {
          "$ref": "#/definitions/repoType"
        },
        "url": {
          "$ref": "#/definitions/url"
        },
        "deprecated": {
          "description": "For a deprecated plugin, a deprecation message to be shown to any user who installs the plugin.",
          "type": "string"
        }
      },
      "dependencies": {
        "url": ["type"],
        "type": ["url"]
      }
    },
    "otherRepository": {
      "description": "Info about a plugin/repository outside this one.",
      "type": "object",
      "anyOf": [
        {
          "$comment": "Empty repository info. Used to declare plugin with the given name is required without specifying any explicit details about how to fetch it (e.g., if name can be looked up in a predefined package index).",
          "additionalProperties": false
        },
        {
          "$comment": "Repository with empty type and url pointing to local path.",
          "properties": {
            "type": {
              "enum": ["", "archive"]
            },
            "url": {
              "$ref": "#/definitions/url"
            },
            "vim_script_nr": {
              "description": "Script ID number of the target plugin on www.vim.org, if any.",
              "type": "number",
              "examples": [31, 1075]
            },
            "script-type": {
              "enum": [
                "color scheme",
                "ftplugin",
                "game",
                "indent",
                "syntax",
                "utility",
                "patch"
              ]
            }
          }
        },
        {
          "$comment": "Explicit remote repository.",
          "properties": {
            "type": {
              "$ref": "#/definitions/repoType"
            },
            "url": {
              "$ref": "#/definitions/url"
            }
          },
          "required": ["type", "url"]
        }
      ],
      "properties": {
        "homepage": {
          "description": "Primary homepage of the plugin.",
          "type": "string",
          "format": "uri"
        },
        "addon-info": {
          "$comment": "Addon information for the other plugin in case it does not supply its own addon-info file.",
          "$ref": "#"
        }
      }
    }
  },
  "properties": {
    "name": {
      "description": "The name of the plugin. Used by plugin managers and some introspection tools. Generally corresponds to the name of the repository but without \"vim\" prefix/suffix.",
      "type": "string",
      "examples": ["surround.vim", "nerdtree", "maktaba"]
    },
    "version": {
      "description": "Dotted version number of the plugin, generally in semantic versioning scheme.",
      "type": "string",
      "examples": ["0.0.1", "2.0"],
      "default": "0.0.1"
    },
    "description": {
      "description": "Short description of the plugin and what it does (a sentence or two)",
      "type": "string"
    },
    "homepage": {
      "description": "Primary homepage of the plugin.",
      "type": "string",
      "format": "uri"
    },
    "author": {
      "description": "Name of the person or organization that created the plugin",
      "type": "string",
      "examples": ["Priya Exampleton", "Example Industries"]
    },
    "maintainer": {
      "description": "Name of the person who maintains the plugin",
      "type": "string",
      "examples": ["Priya Exampleton"]
    },
    "repository": {
      "$ref": "#/definitions/selfRepository"
    },
    "dependencies": {
      "description": "Plugins that are strictly required for the plugin to work, where keys are plugin names and values may describe where plugins can be fetched from.",
      "type": "object",
      "additionalProperties": {
        "$ref": "#/definitions/otherRepository"
      }
    }
  },
  "title": "JSON schema for vim plugin addon-info.json metadata files",
  "type": "object"
}

{
  "$id": "https://aka.ms/winget-manifest.locale.1.0.0.schema.json",
  "$schema": "http://json-schema.org/draft-07/schema#",
  "definitions": {
    "Url": {
      "type": ["string", "null"],
      "pattern": "^([Hh][Tt][Tt][Pp][Ss]?)://.+$",
      "maxLength": 2000,
      "description": "Optional Url type"
    },
    "Tag": {
      "type": ["string", "null"],
      "minLength": 1,
      "maxLength": 40,
      "description": "Package moniker or tag"
    }
  },
  "description": "A representation of a multiple-file manifest representing app metadata in other locale in the OWC. v1.0.0",
  "properties": {
    "PackageIdentifier": {
      "type": "string",
      "pattern": "^[^\\.\\s\\\\/:\\*\\?\"<>\\|\\x01-\\x1f]{1,32}(\\.[^\\.\\s\\\\/:\\*\\?\"<>\\|\\x01-\\x1f]{1,32}){1,3}$",
      "maxLength": 128,
      "description": "The package unique identifier"
    },
    "PackageVersion": {
      "type": "string",
      "pattern": "^[^\\\\/:\\*\\?\"<>\\|\\x01-\\x1f]+$",
      "maxLength": 128,
      "description": "The package version"
    },
    "PackageLocale": {
      "type": "string",
      "pattern": "^([a-zA-Z]{2}|[iI]-[a-zA-Z]+|[xX]-[a-zA-Z]{1,8})(-[a-zA-Z]{1,8})*$",
      "maxLength": 20,
      "description": "The package meta-data locale"
    },
    "Publisher": {
      "type": ["string", "null"],
      "minLength": 2,
      "maxLength": 256,
      "description": "The publisher name"
    },
    "PublisherUrl": {
      "$ref": "#/definitions/Url",
      "description": "The publisher home page"
    },
    "PublisherSupportUrl": {
      "$ref": "#/definitions/Url",
      "description": "The publisher support page"
    },
    "PrivacyUrl": {
      "$ref": "#/definitions/Url",
      "description": "The publisher privacy page or the package privacy page"
    },
    "Author": {
      "type": ["string", "null"],
      "minLength": 2,
      "maxLength": 256,
      "description": "The package author"
    },
    "PackageName": {
      "type": ["string", "null"],
      "minLength": 2,
      "maxLength": 256,
      "description": "The package name"
    },
    "PackageUrl": {
      "$ref": "#/definitions/Url",
      "description": "The package home page"
    },
    "License": {
      "type": ["string", "null"],
      "minLength": 3,
      "maxLength": 512,
      "description": "The package license"
    },
    "LicenseUrl": {
      "$ref": "#/definitions/Url",
      "description": "The license page"
    },
    "Copyright": {
      "type": ["string", "null"],
      "minLength": 3,
      "maxLength": 512,
      "description": "The package copyright"
    },
    "CopyrightUrl": {
      "$ref": "#/definitions/Url",
      "description": "The package copyright page"
    },
    "ShortDescription": {
      "type": ["string", "null"],
      "minLength": 3,
      "maxLength": 256,
      "description": "The short package description"
    },
    "Description": {
      "type": ["string", "null"],
      "minLength": 3,
      "maxLength": 10000,
      "description": "The full package description"
    },
    "Moniker": {
      "$ref": "#/definitions/Tag",
      "description": "The most common package term"
    },
    "Tags": {
      "type": ["array", "null"],
      "items": {
        "$ref": "#/definitions/Tag"
      },
      "maxItems": 16,
      "uniqueItems": true,
      "description": "List of additional package search terms"
    },
    "ManifestType": {
      "type": "string",
      "default": "locale",
      "const": "locale",
      "description": "The manifest type"
    },
    "ManifestVersion": {
      "type": "string",
      "default": "1.0.0",
      "pattern": "^(0|[1-9][0-9]{0,3}|[1-5][0-9]{4}|6[0-4][0-9]{3}|65[0-4][0-9]{2}|655[0-2][0-9]|6553[0-5])(\\.(0|[1-9][0-9]{0,3}|[1-5][0-9]{4}|6[0-4][0-9]{3}|65[0-4][0-9]{2}|655[0-2][0-9]|6553[0-5])){2}$",
      "description": "The manifest syntax version"
    }
  },
  "required": [
    "PackageIdentifier",
    "PackageVersion",
    "PackageLocale",
    "ManifestType",
    "ManifestVersion"
  ],
  "type": "object"
}

{
  "$comment": "https://developer.chrome.com/docs/extensions/mv3/i18n-messages/",
  "$id": "https://json.schemastore.org/chrome-extension-locales-messages.json",
  "$schema": "http://json-schema.org/draft-07/schema#",
  "additionalProperties": false,
  "patternProperties": {
    "^(?!@@)[\\w@]+$": {
      "properties": {
        "message": {
          "description": "The translated message, in the form of a string that can contain placeholders. Use `$_placeholder_name_$` (case insensitive) to refer to a particular placeholder. For example, you can refer to a placeholder named \"our_site\" as `$our_site$`, `$OUR_SITE$`, or `$oUR_sITe$`.\nTo put a dollar sign (`$`) into the string, use `$$`.\nAlthough placeholders such as `$USER$` are the preferred way of referring to substitution strings (strings specified using the substitutions parameter of i18n.getMessage) you can also refer to substitution strings directly within the message.",
          "examples": [
            "What's your name?",
            "Hello, $USER$",
            "Goodbye, $USER$. Come back to $OUR_SITE$ soon!",
            "Amount (in $$)",
            "Params: $1, $2, $3"
          ],
          "type": "string",
          "title": "message"
        },
        "description": {
          "description": "Optional. A description of the message, intended to give context or details to help the translator make the best possible translation.",
          "examples": [
            "Ask for the user's name",
            "Greet the user",
            "Say goodbye to the user"
          ],
          "type": "string",
          "title": "description"
        },
        "placeholders": {
          "description": "Optional. Defines one or more substrings to be used within the message.\nEach placeholder has a name, a \"content\" item, and an optional \"example\" item. A placeholder's name is case-insensitive and can contain the same characters as a message name.\n",
          "patternProperties": {
            "^[\\w@]+$": {
              "properties": {
                "content": {
                  "description": "The \"content\" item's value is a string that can refer to substitution strings, which are specified using the i18n.getMessage method's substitutions parameter. The value of a \"content\" item is typically something like \"Example.com\" or \"$1\". If you refer to a substitution string that doesn't exist, you get an empty string. The following table shows how `$_n_` strings correspond to strings specified by the substitutions parameter.",
                  "type": "string",
                  "title": "content"
                },
                "example": {
                  "description": "The \"example\" item (optional, but highly recommended) helps translators by showing how the content appears to the end user. For example, a placeholder for a dollar amount should have an example like `\"$23.45\"`.",
                  "type": "string",
                  "title": "example"
                }
              },
              "required": ["content"],
              "type": "object"
            }
          },
          "type": "object",
          "title": "placeholders"
        }
      },
      "required": ["message"],
      "type": "object"
    }
  },
  "type": "object"
}

