              "oneOf": [
                {
                  "$ref": "#/definitions/mergeJson"
                },
                {
                  "$ref": "#/definitions/mergeYaml"
                },
                {
                  "$ref": "#/definitions/mergeGit"
                },
                {
                  "$ref": "#/definitions/mergeEnv"
